fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Assume arr1.len() == arr2.len() and no overflow occurs when summing.
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(a, b)| a + b)
        .collect()
}

